//! Generator for `src/hash/pedersen_tables.rs` (`@generated` constants).
//!
//! Emits, using only the public API:
//! - `PEDERSEN_SEG_TABLES`: per segment `s` (6) and chunk `k` (63) the
//!   multiples `[1,2,3,4]·16^k·G_s` as extended-coordinate limbs
//!   (`[x, y, z, t]`, each big-endian `[u64; 4]`).
//! - `PEDERSEN_DUAL_TABLES`: same multiples in dual `(y−x, y+x, 2·d·t)`
//!   Montgomery limbs (`[[[u64; 4]; 3]; 8]`, slots `[2v, 2v+1]` hold the
//!   positive and negated forms) for `add_dual_vartime`. Edwards `d` is
//!   re-derived from the curve equation (cross-checked on a second
//!   generator before emitting).
//! - `SAPLING_EMPTY_CHAIN` / `ORCHARD_EMPTY_CHAIN`: empty-subtree roots
//!   `E[0..=32]` as node bytes (layer `l` folds with its own layer
//!   personalization, exactly like `empty_root`).
//! - `SINS_MERKLE_Q`: the Sinsemilla Orchard-MerkleCRH domain point as
//!   Montgomery `(x, y)` limbs.
//!
//! Run: `cargo run --example gen_pedersen_tables --features zcash-sapling`
//! and redirect stdout to `src/hash/pedersen_tables.rs`. Then run the
//! `tables_match_live` test plus the full KAT suites before committing.

use blockchain_utils::curve::jubjub::{Fe, JubJubPoint};
use blockchain_utils::curve::traits::CurvePoint;
use blockchain_utils::hash::pedersen::{PedersenHash, Personalization};
use blockchain_utils::hash::sinsemilla::Sinsemilla;
use blockchain_utils::zk::incrementalmerkletree::bridge::{OrchardNode, SaplingNode};
use blockchain_utils::zk::incrementalmerkletree::{Hashable, Level};

fn be_limbs(bytes: &[u8; 32]) -> [u64; 4] {
    let mut out = [0u64; 4];
    for i in 0..4 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&bytes[i * 8..(i + 1) * 8]);
        out[i] = u64::from_be_bytes(b);
    }
    out
}

fn fmt_limbs(limbs: &[u64; 4]) -> String {
    format!(
        "[{:#018x}, {:#018x}, {:#018x}, {:#018x}]",
        limbs[0], limbs[1], limbs[2], limbs[3]
    )
}

fn fe_limbs(fe: &Fe) -> [u64; 4] {
    let mut be = [0u8; 32];
    fe.to_bytes_be(&mut be);
    be_limbs(&be)
}

/// Extended coords of `p` via affine round-trip: `(u, v, 1, u·v)`.
fn ext_limbs(p: &JubJubPoint) -> [[u64; 4]; 4] {
    let (u, v) = p.affine_uv().expect("affine");
    let t = u.mul(&v);
    let mut one = [0u8; 32];
    Fe::one().to_bytes_be(&mut one);
    [fe_limbs(&u), fe_limbs(&v), be_limbs(&one), fe_limbs(&t)]
}

fn main() {
    println!("// @generated by `examples/gen_pedersen_tables.rs` — DO NOT EDIT.");
    println!("// Pedersen segment windows, empty chains, Sinsemilla MerkleCRH point.");
    println!(
        "// Regenerate with: `cargo run --example gen_pedersen_tables --features zcash-sapling`."
    );
    println!("// Tables below are raw limbs/bytes (no curve imports needed);");
    println!("// consumers assemble points with const constructors.");
    println!();

    // --- Segment tables: [1,2,3,4]·16^k·G_s, s in 0..6, k in 0..63. ---
    println!("/// `TABLES[s][k] = [1,2,3,4]·16^k·G_s` (extended coords).");
    println!("pub static PEDERSEN_SEG_TABLES: [[[[[u64; 4]; 4]; 4]; 63]; 6] = [");
    let ph = PedersenHash::new().expect("gens");
    for gen0 in ph.gens.iter() {
        println!("    [");
        let mut gen = *gen0;
        for _ in 0..63 {
            // coeffs[j] = (j+1)·gen.
            let mut g = gen;
            let mut line = String::from("        [");
            for j in 0..4 {
                if j > 0 {
                    g = g.add(&gen);
                }
                let e = ext_limbs(&g);
                line.push_str(&format!(
                    "[{}, {}, {}, {}]{}",
                    fmt_limbs(&e[0]),
                    fmt_limbs(&e[1]),
                    fmt_limbs(&e[2]),
                    fmt_limbs(&e[3]),
                    if j == 3 { "" } else { ", " }
                ));
            }
            line.push_str("],");
            println!("{line}");
            // Advance base by 2^4.
            for _ in 0..4 {
                gen = gen.double();
            }
        }
        println!("    ],");
    }
    println!("];");
    println!();

    // --- Empty chains (layer-personalized folds, like `empty_root`). ---
    println!("/// Sapling empty-subtree roots `E[0..=32]` (node bytes LE).");
    println!("pub static SAPLING_EMPTY_CHAIN: [[u8; 32]; 33] = [");
    let mut e = SaplingNode::empty_leaf();
    for l in 0..33u8 {
        println!(
            "    [{}],",
            e.0.iter()
                .map(|b| format!("{b:#04x}"))
                .collect::<Vec<_>>()
                .join(", ")
        );
        e = SaplingNode::combine(Level::from(l), &e, &e);
    }
    println!("];");
    println!();
    println!("/// Orchard empty-subtree roots `E[0..=32]` (node bytes LE).");
    println!("pub static ORCHARD_EMPTY_CHAIN: [[u8; 32]; 33] = [");
    let mut o = OrchardNode::empty_leaf();
    for l in 0..33u8 {
        println!(
            "    [{}],",
            o.0.iter()
                .map(|b| format!("{b:#04x}"))
                .collect::<Vec<_>>()
                .join(", ")
        );
        o = OrchardNode::combine(Level::from(l), &o, &o);
    }
    println!("];");
    println!();

    // --- Sinsemilla MerkleCRH domain point (Montgomery limbs). ---
    let (qx, qy) = Sinsemilla::from_domain("z.cash:Orchard-MerkleCRH")
        .expect("domain")
        .domain_point_limbs();
    // NOTE: `pub const` (not static) so `sinsemilla::MERKLE_CRH` can be
    // assembled in const context; the big tables stay `static` (one image).
    println!("/// Sinsemilla Orchard-MerkleCRH domain point (Montgomery limbs).");
    println!("pub const SINS_MERKLE_Q: ([u64; 4], [u64; 4]) = (");
    println!("    {},", fmt_limbs(&qx));
    println!("    {},", fmt_limbs(&qy));
    println!(");");
    println!();

    // --- Dual-form Pedersen windows (Montgomery limbs, affine z=1). ---
    // `DUAL[s][k][2v] = dual((v+1)·16^k·G_s)`, `[2v+1] = its negation`,
    // each as `(y−x, y+x, 2·d·t)` Montgomery limbs for
    // `JubJubPoint::add_dual_vartime`. Edwards `d` is re-derived from the
    // curve equation on G0 (`-x²+y² = 1+d·x²y²`, public ops only — no
    // private constants), then cross-checked on G1 before emitting.
    let (g0u, g0v) = {
        let (u, v) = ph.gens[0].affine_uv().expect("g0 affine");
        (u, v)
    };
    let x2 = g0u.mul(&g0u);
    let y2 = g0v.mul(&g0v);
    let d = y2
        .sub(&x2)
        .sub(&Fe::one())
        .mul(&x2.mul(&y2).invert().expect("d invert"));
    // Cross-check on G1 (loud failure if the formula is wrong).
    {
        let (u1, v1) = ph.gens[1].affine_uv().expect("g1 affine");
        let lhs = v1.mul(&v1).sub(&u1.mul(&u1));
        let rhs = Fe::one().add(&d.mul(&u1.mul(&u1)).mul(&v1.mul(&v1)));
        // NOTE: Fe has no PartialEq here; compare canonical bytes.
        let mut lb = [0u8; 32];
        let mut rb = [0u8; 32];
        lhs.to_bytes_be(&mut lb);
        rhs.to_bytes_be(&mut rb);
        assert_eq!(lb, rb, "edwards d cross-check on G1");
    }
    let two_d = d.add(&d);
    println!("/// Dual Pedersen windows `DUAL[s][k][2v]/[2v+1]` =");
    println!("/// `(y−x, y+x, 2·d·t)` Montgomery limbs for v+1 in 1..=4");
    println!("/// (negated slots precomputed; affine z=1 by construction).");
    println!("pub static PEDERSEN_DUAL_TABLES: [[[[[u64; 4]; 3]; 8]; 63]; 6] = [");
    for gen0 in ph.gens.iter() {
        println!("    [");
        let mut gen = *gen0;
        for _ in 0..63 {
            let mut g = gen;
            // Flat 8 slots per chunk: [pos(v), neg(v)] for v = 1..=4.
            let mut slots: Vec<String> = Vec::new();
            for _ in 0..4 {
                let (u, v) = g.affine_uv().expect("affine");
                let t = u.mul(&v);
                let ymx = v.sub(&u);
                let ypx = v.add(&u);
                let c = two_d.mul(&t);
                let nc = c.neg();
                slots.push(format!(
                    "[{}, {}, {}]",
                    fmt_limbs(&ymx.to_mont_limbs()),
                    fmt_limbs(&ypx.to_mont_limbs()),
                    fmt_limbs(&c.to_mont_limbs()),
                ));
                slots.push(format!(
                    "[{}, {}, {}]",
                    fmt_limbs(&ypx.to_mont_limbs()),
                    fmt_limbs(&ymx.to_mont_limbs()),
                    fmt_limbs(&nc.to_mont_limbs()),
                ));
                g = g.add(&gen);
            }
            println!("        [{}],", slots.join(", "));
            for _ in 0..4 {
                gen = gen.double();
            }
        }
        println!("    ],");
    }
    println!("];");

    // Silence unused warnings for the personalization import path.
    let _ = Personalization::NoteCommitment;
}
